// Block (composition) — consumer-supplied form fields arranged inside the Drawer Component.
// Drawer owns overlay behavior; Form owns form semantics and validation context.
// `responsive` opens it as Drawer's `sheet`: a bottom sheet below the `large` breakpoint and a centred
// panel at and above it, one overlay whose box moves, so an open form keeps its values across the line.
//
// The secondary action closes by default. Given `onReset` it RESETS instead and the panel stays
// open, the footer a filter sheet ends in: reset beside a primary that says what it will show. The
// count in that label is the consumer's: `submitLabel` is rendered as given, so a label computed
// from the pending choices ("Show 329 plans") updates live as they change, before anything applies.
//
// A submit closes the panel once `onSubmit` has run, through React Aria's OverlayTriggerStateContext,
// the state the trigger hands every overlay it opens. Returning `false` from `onSubmit` keeps it open.
import { useId } from "react";
import type { FormEvent, ReactNode } from "react";
import {
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "../components/Drawer";
import { OverlayTriggerStateContext } from "react-aria-components";
import { Form } from "../components/Form";
import { Button } from "../components/Button";
import { Undo } from "../components/icons";
import { Stack } from "../layouts/Stack";
import "./DrawerForm.css";

export interface DrawerFormProps {
  /** Control that opens the drawer. */
  trigger: ReactNode;
  /** Drawer heading. */
  title: string;
  /** One line under the heading saying what the form decides. */
  description?: string;
  /** Accessible name of the close (X) button, for a screen that is not in English.
      @default "Close" */
  closeLabel?: string;
  /** Form fields supplied by the consumer. */
  children: ReactNode;
  /** Submit action label. */
  submitLabel?: string;
  /** Secondary action label. It closes the panel without submitting. Unused when `onReset` is set.
   * @default "Cancel"
   */
  cancelLabel?: string;
  /** Turns the secondary action into a reset: pressing it calls this and the panel stays open. The
   *  consumer clears its own field state here, so the fields are controlled in this mode. */
  onReset?: () => void;
  /** The reset action's label. Used only with `onReset`.
   * @default "Reset"
   */
  resetLabel?: string;
  /** Disables the reset while there is nothing to reset (no pending choice differs from the
   *  cleared state). Used only with `onReset`. */
  isResetDisabled?: boolean;
  /** Called with string-normalized form values on submit. The panel then closes, unless this
   *  returns `false`, which keeps it open: return it when a check of your own fails. Fields that
   *  fail their own validation never reach this, since React Aria's Form withholds the submit. */
  onSubmit?: (data: Record<string, string>) => void | false;
  /** Puts the submit action in a pending state and blocks re-submit. */
  isPending?: boolean;
  /** How the panel attaches to the viewport, forwarded to DrawerContent: `inset` is a floating
   *  card, `full-bleed` a panel that touches the edge it docks to. A product picks one for every
   *  sheet it shows.
   * @default "inset"
   */
  variant?: "inset" | "full-bleed";
  /** Edge the drawer slides from. Ignored when `responsive` is set. */
  side?: "start" | "end";
  /** A bottom sheet below the `large` breakpoint, a centred panel at and above it.
   * @default false
   */
  responsive?: boolean;
}

/** The submitted form's values, each normalized to a string. */
function readForm(event: FormEvent<HTMLFormElement>) {
  const data: Record<string, string> = {};
  new FormData(event.currentTarget).forEach((value, key) => {
    data[key] = String(value);
  });
  return data;
}

export function DrawerForm({
  trigger,
  title,
  description,
  closeLabel,
  children,
  submitLabel = "Save",
  cancelLabel = "Cancel",
  onReset,
  resetLabel = "Reset",
  isResetDisabled,
  onSubmit,
  isPending,
  variant,
  side = "end",
  responsive = false,
}: DrawerFormProps) {
  const formId = useId();

  return (
    <DrawerTrigger>
      {trigger}
      <DrawerContent variant={variant} side={responsive ? "sheet" : side} className="sd-drawerform" closeLabel={closeLabel}
        header={
          <DrawerHeader>
            <DrawerTitle>{title}</DrawerTitle>
            {description && <DrawerDescription>{description}</DrawerDescription>}
          </DrawerHeader>
        }
        footer={
          // With a reset the primary fills the row and the reset hugs (`fill`), as RangeFilterSheet's
          // footer does: the reset is a tool beside the one way forward, not its peer.
          <DrawerFooter layout={onReset ? "fill" : "end"}>
            {onReset ? (
              /* usage: completing-action — clears the pending choices, the panel stays open */
              <Button size="large" type="button" variant="secondary" isDisabled={isResetDisabled} onPress={onReset}>
                <Undo aria-hidden size="1em" />
                {resetLabel}
              </Button>
            ) : (
              /* usage: completing-action — the footer that ends the form */
              <Button size="large" type="button" variant="secondary" slot="close">
                {cancelLabel}
              </Button>
            )}
            {/* usage: completing-action — the form's submit, in the same footer */}
            <Button size="large" type="submit" form={formId} variant="primary" isPending={isPending}>
              {submitLabel}
            </Button>
          </DrawerFooter>
        }
      >
        {/* The form stays in the body slot and the actions go in `footer`, which renders below
            the scrolling body at the panel bottom. `form=` keeps the submit button wired to the
            form it sits outside of. */}
        {/* The overlay state is read here, inside the panel, because only what the trigger
            renders sees it. */}
        <OverlayTriggerStateContext.Consumer>
          {(overlay) => (
            <Form
              isPending={isPending}
              id={formId}
              onSubmit={(event) => {
                // The drawer owns the submit whether or not a handler is given: a native submit
                // would navigate the page away from the open panel.
                event.preventDefault();
                if (onSubmit?.(readForm(event)) !== false) overlay?.close();
              }}
            >
              <Stack gap="medium" className="sd-drawerform__fields">
                {children}
              </Stack>
            </Form>
          )}
        </OverlayTriggerStateContext.Consumer>
      </DrawerContent>
    </DrawerTrigger>
  );
}
